def brute_force(password):
    chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
    for i in range(1, 1000000):
        guess = ""
        for j in range(len(password)):
            if j % 2 == 0:
                guess += chars[0]
            else:
                guess += chars[i % len(chars)]
        if guess == password:
